prompt:
{
  "public_instructions": "You translate natural-language access-control requirements into Cedar policies using the supplied schema. Cedar denies by default. An applicable forbid overrides every permit. Guard optional attributes with has before reading them. Preserve the schema's entity, set, and attribute types. Use only the supplied task information. Do not use tools, files, search, additional model calls, or external feedback. Produce a single final answer as a JSON object with exactly one field, policy, whose value is the complete Cedar policy text. Do not include explanations or Markdown fences.
",
  "harness": {
    "instruction_blocks": [
      "Translate the access-control requirements into a complete Cedar policy set. Identify each action, eligible principal, resource type, required condition, prohibition, and exception. Use only entity types, attributes, actions, and representations supported by the schema. Implement the stated permissions and restrictions together.",
      "Before answering, check the policy mentally for both unauthorized permissions and missing required permissions. Keep distinct action rules separate when their conditions differ. Apply exceptions only to the restriction they qualify. Return one final policy set."
    ],
    "input_order": [
      "requirements",
      "schema"
    ],
    "checklist": [
      "Every required action is covered.",
      "Role, ownership, membership, and context conditions follow the requirements.",
      "Prohibitions and exceptions compose correctly.",
      "Optional attribute reads are guarded and Cedar syntax is valid."
    ]
  },
  "requirements": "This document sets out who may approve grant awards and obligate their funds in the federal grant award management system.
The people involved are reviewers, program officers, grants officers, and applicants; one person may act as both a reviewer and a program officer, and one person may act as both a program officer and a grants officer.
The resources are applications, which record their applicant, assigned reviewers, funding tier, requested amount, program code, and status; and awards, which record their application, who approved them, who obligated their funds, their amount, whether they are flagged high risk, and their status.
Each request carries the current time, whether it comes from the government network, and whether an emergency has been declared.
In this workflow an award is first approved and then its funds are obligated, and the obligation step can see the award's status, who approved it, and who obligated it.
A program officer or grants officer may approve an award only when their approval authority is at or above the application's funding tier, and when their authority falls below that tier the approval must not proceed.
The grants officer who approved an award must not obligate its funds, so the obligation must fall to a different grants officer.
Funds may be obligated only when the requester holds the designated role, and when the requester lacks that role the obligation must not proceed.
A run through the workflow by a program officer that trips none of the prohibitions above must be able to succeed.",
  "schema": "entity Role enum ["Reviewer", "ProgramOfficer", "GrantsOfficer", "Applicant"];

entity User {
    roles: Set<Role>,
    approvalAuthority: Long,
};

entity Application {
    applicant: User,
    assignedReviewers: Set<User>,
    fundingTier: Long,
    requestedAmount: decimal,
    programCode: String,
    status: String,
};

entity Award {
    application: Application,
    approvedBy?: User,
    obligatedBy?: User,
    amount: decimal,
    highRisk: Bool,
    status: String,
};

action approveAward appliesTo {
    principal: [User],
    resource: [Award],
    context: {
        currentTime: datetime,
        fromGovernmentNetwork: Bool,
        emergencyDeclared: Bool,
    },
};

action obligateFunds appliesTo {
    principal: [User],
    resource: [Award],
    context: {
        currentTime: datetime,
        fromGovernmentNetwork: Bool,
        emergencyDeclared: Bool,
    },
};
"
}
